function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 2 || s.length > 100000) return 's needs 2 to 100000 characters.';
  if (s.length % 2 === 1) return 's must have an even length.';
  if (!/^[01]+$/.test(s)) return 's may contain only 0 and 1.';
  return null;
}

