function minChanges(s) {
  // Try every binary string of the same length and keep the beautiful ones.
  const n = s.length;
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    let target = '';
    for (let i = 0; i < n; i++) target += (mask >> i) & 1 ? '1' : '0';
    let beautiful = true;
    let start = 0;
    for (let i = 1; i <= n; i++) {
      if (i === n || target[i] !== target[start]) {
        if ((i - start) % 2 === 1) beautiful = false;
        start = i;
      }
    }
    if (!beautiful) continue;
    let diff = 0;
    for (let i = 0; i < n; i++) if (target[i] !== s[i]) diff++;
    best = Math.min(best, diff);
  }
  return best;
}

