function generate(rand, size) {
  const n = size === 'large' ? 2 * (4000 + Math.floor(rand() * 1001)) : 2 * (1 + Math.floor(rand() * 6));
  // Build the string from runs so both long blocks and rapid alternation appear.
  const meanRun = 1 + Math.floor(rand() * (size === 'large' ? 12 : 4));
  let s = '';
  let bit = rand() < 0.5 ? '0' : '1';
  while (s.length < n) {
    const run = 1 + Math.floor(rand() * meanRun);
    s += bit.repeat(Math.min(run, n - s.length));
    bit = bit === '0' ? '1' : '0';
  }
  return [s];
}
